#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100

/** 并查集定义 **/
typedef struct {
    int *fa;
} UFS;

UFS *new_UFS(int n) {
    UFS *ufs = (UFS *) malloc(sizeof(UFS));

    ufs->fa = (int *) malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        ufs->fa[i] = i;
    }

    return ufs;
}

int find_UFS(UFS *ufs, int x) {
    if (x != ufs->fa[x]) {
        ufs->fa[x] = find_UFS(ufs, ufs->fa[x]);
        return ufs->fa[x];
    }
    return x;
}

void union_UFS(UFS *ufs, int x, int y) {
    int x_fa = find_UFS(ufs, x);
    int y_fa = find_UFS(ufs, y);

    if (x_fa != y_fa) {
        ufs->fa[y_fa] = x_fa;
    }
}

int main() {
    int n;
    scanf("%d", &n);

    int confirmed[MAX_SIZE];
    int confirmed_size = 0;

    while (scanf("%d", &confirmed[confirmed_size++])) {
        if (getchar() != ',') break;
    }

    UFS *ufs = new_UFS(n);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int v;
            scanf("%d", &v);

            // 有过接触的人进行合并
            if (v == 1) {
                union_UFS(ufs, i, j);
            }

            getchar();
        }
    }

    // 统计每个接触群体（连通分量）中的人数
    int cnts[MAX_SIZE] = {0};
    for (int i = 0; i < n; i++) {
        int fa = find_UFS(ufs, i);
        cnts[fa]++;
    }

    // 记录已统计过的可能感染群体
    int confirmed_fa[MAX_SIZE] = {0};

    // 将有感染者的接触群体的人数统计出来
    int ans = 0;
    for (int i = 0; i < confirmed_size; i++) {
        int fa = find_UFS(ufs, confirmed[i]);

        // 已统计过的可能感染群体不再统计
        if(confirmed_fa[fa]) continue;
        confirmed_fa[fa] = 1;

        ans += cnts[fa];
    }

    // 最终需要做核酸的人数，不包括已感染的人
    printf("%d\n", ans - confirmed_size);

    return 0;
}
